from pathlib import Path
import json, re, html, unicodedata
from collections import Counter
import numpy as np
import pandas as pd
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity
import plotly.graph_objects as go
from plotly.utils import PlotlyJSONEncoder

ROOT=Path(__file__).resolve().parent.parent
frames=[]
for split in ['train','valid','test']:
 d=pd.read_csv(ROOT/'data'/f'victsd_{split}.csv');d['Split']=split;frames.append(d)
df=pd.concat(frames,ignore_index=True)
train=frames[0].copy()
stop=set('và là có của cho trong với những các được không một này người thì mà đã như để khi từ về cũng rất vào ra ở trên dưới lại tôi bạn họ nó chúng ta hay nhưng nên sẽ bị vì nếu còn đó đây theo qua với đến sau trước hơn nhất nào gì sao cả thôi rồi đang cái ấy thế mọi mỗi ai nhiều ít việc mình phải làm nói biết thấy thật luôn quá đã vì được mà thì là có các những'.split())
token_re=re.compile(r'[^\W\d_]+',re.UNICODE)
def tokens(s): return token_re.findall(unicodedata.normalize('NFC',str(s)).lower())
def normalize(s):
 s=str(s).lower();s=re.sub(r'https?://\S+|www\.\S+',' ',s);s=re.sub(r'[^\w\s]',' ',s);return re.sub(r'\s+',' ',s).strip()
df['Chars']=df.Comment.str.len();df['Words']=df.Comment.map(lambda x:len(str(x).split()))
train['tokens']=train.Comment.map(tokens);train['content']=train.tokens.map(lambda t:[w for w in t if w not in stop]);train['norm']=train.Comment.map(normalize)
all_norm=df.Comment.map(normalize); trainset=set(train.norm)
valid_overlap=sum(frames[1].Comment.map(normalize).isin(trainset));test_overlap=sum(frames[2].Comment.map(normalize).isin(trainset))
colors=['#17666a','#e06b42','#466dab','#d5a342','#856aad','#62a58c','#c46c90','#7c8d55','#8d6a55','#467b9e']
plots=[]
def graph(fig):
 fig.update_layout(template='plotly_white',font=dict(family='Arial',size=13,color='#18333a'),paper_bgcolor='white',plot_bgcolor='white',margin=dict(l=65,r=25,t=45,b=70),height=410,legend=dict(orientation='h',y=-.25))
 i=len(plots);plots.append(json.loads(json.dumps(fig,cls=PlotlyJSONEncoder)));return f'<div class="chart" id="plot-{i}" role="img" aria-label="Biểu đồ tương tác"></div>'
def bar(series,title,xlabel='Số bình luận',color='#17666a',height=None):
 s=series.sort_values(); fig=go.Figure(go.Bar(x=s.values.tolist(),y=s.index.astype(str).tolist(),orientation='h',marker_color=color,hovertemplate='%{y}: %{x}<extra></extra>'));fig.update_layout(title=title,xaxis_title=xlabel);return graph(fig)
def panel(title,intro,chart,explain,method,code):
 return f'''<section class="section"><div class="section-top"><h2>{title}</h2><span>{method}</span></div><p>{intro}</p>{chart}<div class="interpret"><strong>Cách đọc và trình bày</strong><p>{explain}</p></div><details><summary>Xem cách thực hiện</summary><pre><code>{html.escape(code)}</code></pre><button type="button" class="copy">Sao chép mã</button></details></section>'''
sections=[]
sections.append(panel('1. Các tập dữ liệu','Dữ liệu có ba tập chính thức; số dòng thể hiện quy mô của từng tập.',bar(df.Split.value_counts(),'Số bình luận theo tập'), 'Train dùng để học; validation dùng so sánh lựa chọn; test dùng đánh giá cuối. Báo cáo mô tả này thống kê cả ba tập, nhưng phân tích từ vựng bên dưới chỉ dùng train để tránh dùng test định hướng mô hình.','Toàn bộ dữ liệu',"df.groupby('Split').size()"))
fig=go.Figure()
for col,name in [('Toxicity','Độc hại'),('Constructiveness','Tính xây dựng')]:
 c=df[col].value_counts().reindex([0,1],fill_value=0);fig.add_bar(name=name,x=['Nhãn 0','Nhãn 1'],y=c.tolist())
fig.update_layout(barmode='group',title='Hai bài toán nhị phân',yaxis_title='Số bình luận',colorway=colors)
sections.append(panel('2. Phân phối nhãn','Mỗi bình luận có hai nhãn riêng: Toxicity và Constructiveness; nhãn 1 tương ứng với có tính chất đó.',graph(fig),'Hai bài toán không loại trừ nhau. Nếu lớp 1 ít hơn nhiều, accuracy có thể che giấu việc dự đoán kém lớp ít; nên xem precision, recall và F1 theo lớp.','Toàn bộ dữ liệu',"df[['Toxicity', 'Constructiveness']].apply(pd.Series.value_counts)"))
ct=pd.crosstab(df.Constructiveness,df.Toxicity);fig=go.Figure(go.Heatmap(z=ct.values.tolist(),x=['Không độc hại (0)','Độc hại (1)'],y=['Không xây dựng (0)','Xây dựng (1)'],colorscale='Teal',text=ct.values.tolist(),texttemplate='%{text}',hovertemplate='%{y}<br>%{x}<br>Số bình luận: %{z}<extra></extra>'));fig.update_layout(title='Hai nhãn xuất hiện cùng nhau như thế nào',xaxis_title='Toxicity',yaxis_title='Constructiveness')
sections.append(panel('3. Quan hệ giữa hai nhãn','Mỗi ô cho biết số bình luận có đồng thời hai giá trị nhãn tương ứng.',graph(fig),'Một bình luận được gán cả hai nhãn, nên hãy đọc theo giao điểm của hàng và cột. Bảng không chứng minh quan hệ nhân quả hay quy tắc tuyệt đối giữa hai tính chất.','Toàn bộ dữ liệu',"pd.crosstab(df['Constructiveness'], df['Toxicity'])"))
sections.append(panel('4. Chủ đề bài viết','Topic là chủ đề của bài viết liên quan đến bình luận, không phải nhãn độc hại.',bar(df.Topic.value_counts(),'Số bình luận theo chủ đề'),'Thanh dài cho thấy chủ đề xuất hiện nhiều trong bộ dữ liệu; số lượng lớn không có nghĩa chủ đề đó độc hại hơn. Nên xem cả tỷ lệ nhãn khi so sánh.','Toàn bộ dữ liệu',"df['Topic'].value_counts()"))
topic=df.groupby('Topic').agg(n=('Toxicity','size'),toxic=('Toxicity','mean')).sort_values('toxic');fig=go.Figure(go.Bar(x=(topic.toxic*100).round(2).tolist(),y=topic.index.tolist(),orientation='h',customdata=topic.n.tolist(),marker_color='#e06b42',hovertemplate='%{y}: %{x:.2f}%<br>Số bình luận: %{customdata}<extra></extra>'));fig.update_layout(title='Tỷ lệ nhãn độc hại theo chủ đề',xaxis_title='Tỷ lệ (%)')
sections.append(panel('5. Tỷ lệ độc hại theo chủ đề','Tỷ lệ = số nhãn độc hại / tổng bình luận trong cùng chủ đề.',graph(fig),'Di chuột lên thanh để xem cả mẫu số. Tỷ lệ mô tả các bình luận đã được gán nhãn trong bộ dữ liệu; không suy rộng thành đặc tính của mọi người đọc hay mọi bài báo thuộc chủ đề đó.','Toàn bộ dữ liệu',"df.groupby('Topic')['Toxicity'].agg(['size','mean'])"))
for col,title,xlab in [('Words','6. Độ dài theo số đơn vị tách bằng khoảng trắng','Số đơn vị'),('Chars','7. Độ dài theo ký tự','Số ký tự')]:
 q=df[col].quantile(.99);sub=df[df[col]<=q]; fig=go.Figure(go.Histogram(x=sub[col],nbinsx=45,marker_color='#17666a',hovertemplate='%{x}<br>Số bình luận: %{y}<extra></extra>'));fig.update_layout(title=f'Phân phối độ dài, hiển thị đến phân vị 99% ({q:.0f})',xaxis_title=xlab,yaxis_title='Số bình luận')
 med=df[col].median();sections.append(panel(title,'Độ dài đo trên văn bản gốc, chưa bỏ stopwords; biểu đồ giới hạn phần hiển thị để dễ đọc.',graph(fig),f'Trung vị trên toàn bộ dữ liệu là {med:.0f}. Mốc 99% chỉ ẩn phần đuôi trên khi vẽ, không xóa dữ liệu. Đếm bằng khoảng trắng không phải bộ tách từ tiếng Việt: một từ nhiều âm tiết có thể bị đếm thành nhiều đơn vị.','Toàn bộ dữ liệu',f"length = df['Comment'].str.{'split().str.len()' if col=='Words' else 'len()'}\nlength.hist(bins=45)"))
raw=Counter(w for t in train.tokens for w in t); sw=Counter({w:n for w,n in raw.items() if w in stop}); content=Counter(w for t in train.content for w in t)
sections.append(panel('8. Stopwords trong bình luận','Danh sách minh họa gồm các âm tiết thông dụng như “và”, “của”, “là”. Đây là danh sách tự xác định, không phải chuẩn đầy đủ cho tiếng Việt.',bar(pd.Series(dict(sw.most_common(20))),'20 âm tiết thông dụng xuất hiện nhiều nhất'),'Số lần xuất hiện là tần suất, không phải số bình luận. Việc bỏ stopwords có thể làm mất phủ định hoặc ngữ cảnh; báo cáo này chỉ dùng danh sách để khám phá, không thay đổi pipeline notebook.','Chỉ tập train',"Counter(w for text in train['Comment'] for w in tokenize(text) if w in stopwords)"))
sections.append(panel('9. Âm tiết thường gặp sau lọc','Chuyển về chữ thường, tách chuỗi ký tự chữ và bỏ danh sách stopwords minh họa.',bar(pd.Series(dict(content.most_common(25))),'25 đơn vị xuất hiện nhiều nhất sau lọc'),'Đây là âm tiết/chuỗi chữ, không đảm bảo là từ hoàn chỉnh trong tiếng Việt. Nội dung có thể phản ánh ngôn ngữ nhạy cảm trong dữ liệu; tần suất cao không tự quyết định độc hại.','Chỉ tập train',"Counter(w for words in train_tokens for w in words if w not in stopwords)"))
by=[]
for label in [0,1]:
 ts=train.loc[train.Toxicity==label,'content']; c=Counter(w for t in ts for w in t);by.append((label,c, sum(c.values()),len(c)))
fig=go.Figure();
for label,c,total,unique in by: fig.add_bar(x=[f'Nhãn {label}'],y=[unique],name=f'Nhãn {label}',marker_color=colors[label])
fig.update_layout(title='Số đơn vị duy nhất theo nhãn độc hại',yaxis_title='Số đơn vị khác nhau',showlegend=False)
sections.append(panel('10. Độ phong phú từ vựng','Đếm số đơn vị khác nhau sau lọc stopwords trong từng nhóm nhãn độc hại.',graph(fig),'Nhóm có nhiều bình luận hơn thường có nhiều đơn vị khác nhau hơn. Không kết luận nhóm nào “đa dạng hơn” chỉ từ số đếm tuyệt đối; cần kiểm soát kích thước mẫu để so sánh công bằng.','Chỉ tập train',"len(set(token for tokens in group for token in tokens))"))
for label,c,total,unique in by:
 sections.append(panel(f'11.{label+1}. Từ thường gặp — Toxicity = {label}',f'20 đơn vị phổ biến trong nhóm nhãn {label}; có thể bao gồm từ ngữ nhạy cảm.',bar(pd.Series(dict(c.most_common(20))),f'Tần suất đơn vị — nhãn {label}',color=colors[label]),'Đây là tần suất tuyệt đối trong từng nhóm. Hai nhóm có quy mô khác nhau nên không so sánh trực tiếp chiều dài thanh giữa hai biểu đồ để kết luận mức đặc trưng.','Chỉ tập train',"Counter(w for row in group_tokens for w in row).most_common(20)"))
# TF-IDF fitted to training only; unigram tokens are Vietnamese orthographic syllables.
vectorizer=TfidfVectorizer(token_pattern=r'(?u)\b[^\W\d_]+\b',stop_words=list(stop),ngram_range=(1,1),min_df=3,max_features=10000,sublinear_tf=True)
X=vectorizer.fit_transform(train.Comment.fillna('').str.lower());terms=vectorizer.get_feature_names_out()
for label in [0,1]:
 mask=train.Toxicity.to_numpy()==label; scores=np.asarray(X[mask].mean(axis=0)).ravel(); idx=np.argsort(scores)[-20:];s=pd.Series(scores[idx],index=terms[idx]);sections.append(panel(f'12.{label+1}. TF-IDF trung bình — Toxicity = {label}',f'Giá trị là TF-IDF trung bình của mỗi đơn vị trong các bình luận nhãn {label}.',bar(s,'Các đơn vị có TF-IDF trung bình cao','TF-IDF trung bình',colors[label]),'Điểm cao cho thấy đơn vị có trọng số cao trong nhóm theo cách tính này; không chứng minh đơn vị chỉ xuất hiện ở nhóm đó, cũng không phải hệ số mô hình hay quan hệ nhân quả.','Chỉ tập train',"X = vectorizer.fit_transform(train['Comment'])\nmean_tfidf = X[train['Toxicity'] == label].mean(axis=0)"))
bigrams=Counter((a,b) for t in train.tokens for a,b in zip(t,t[1:]) if a not in stop and b not in stop);b=pd.Series({' '.join(k):v for k,v in bigrams.most_common(20)})
sections.append(panel('13. Cụm hai đơn vị liên tiếp','Đếm hai chuỗi chữ liền kề trong văn bản gốc sau chuẩn hóa chữ thường, chỉ giữ cặp không chứa stopword.',bar(b,'20 cặp xuất hiện nhiều nhất'),'Hai đơn vị có thể ghép thành một từ tiếng Việt, hoặc chỉ là hai âm tiết kề nhau. Không loại stopword trước rồi nối lại, vì làm vậy có thể tạo cặp vốn không liền kề.','Chỉ tập train',"Counter(zip(tokens, tokens[1:]))  # lọc các cặp chứa stopword"))
topics=sorted(train.Topic.unique());means=np.vstack([np.asarray(X[train.Topic.to_numpy()==t].mean(axis=0)).ravel() for t in topics]);sim=cosine_similarity(means);fig=go.Figure(go.Heatmap(z=sim.tolist(),x=topics,y=topics,colorscale='Teal',zmin=0,zmax=1,hovertemplate='%{y} / %{x}: %{z:.3f}<extra></extra>'));fig.update_layout(title='Cosine giữa vector TF-IDF trung bình của từng chủ đề',height=520)
sections.append(panel('14. Độ tương đồng giữa chủ đề','Mỗi chủ đề được biểu diễn bằng vector TF-IDF trung bình của các bình luận trong train; sau đó tính cosine giữa các vector.',graph(fig),'Giá trị càng gần 1 thì hai vector trung bình càng cùng hướng. Đường chéo bằng 1. Đây không phải trung bình cosine của từng cặp bình luận và không có ngưỡng chung đảm bảo mô hình phân loại dễ hay khó.','Chỉ tập train',"centroid = X[train.Topic == topic].mean(axis=0)\ncosine_similarity(centroids)"))
missing=df[['Comment','Topic','Title','Toxicity','Constructiveness']].isna().sum();exact=int(df.Comment.duplicated().sum());normdups=int(all_norm.duplicated().sum());stats=df[['Words','Chars']].describe(percentiles=[.25,.5,.75,.99]).round(1)
def table(frame):return frame.to_html(classes='data',border=0,escape=True)
sections.append(panel('15. Chất lượng dữ liệu và trùng lặp',f'Số dòng lặp nội dung chính xác trên toàn bộ ba tập: <b>{exact:,}</b>; sau chuẩn hóa theo notebook: <b>{normdups:,}</b>.',table(pd.DataFrame({'Ô thiếu':missing})),f'Trong tập validation có {valid_overlap:,} dòng và test có {test_overlap:,} dòng có nội dung sau chuẩn hóa trùng train. Notebook loại những dòng này khi đánh giá; đây là số dòng, không phải số văn bản duy nhất. Việc trùng không tự chứng minh nhãn sai.','Toàn bộ dữ liệu',"train_set = set(train.Comment.map(normalize))\nvalid_overlap = valid.Comment.map(normalize).isin(train_set).sum()"))
